  public void requireUnchanged()throws Exception{owner.require(source,attempt);if(physical.originalAttempt()!=attempt)deny();same(original,owner.readOriginal(source.admission,source.job().runId(),source.stepId(),source.kind()));}
  public FormalEvaluationExecutionProtocol.Artifact artifact(){return original.artifact();}public InterfaceProtocol.ObjectRef reference(){return original.reference();}public String receiptSha256(){return original.receiptSha256();}
