  if(permitted.isEmpty())throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);var roots=new TreeMap<String,PermissionProtocol.Basis>();var graphs=new ArrayList<DependencyLineage.VerifiedLineage>();var versions=new TreeMap<String,ArtifactRegistryProtocol.VersionRow>();String classification=j.classification();
  for(var root:s.roots()){var previous=roots.putIfAbsent(root.version_id(),root);if(previous!=null&&!previous.equals(root))bad();var graph=lineage.inspect(root.version_id(),LIMITS);same(root.content_sha256(),graph.versions().get(root.version_id()).contentSha256());graphs.add(graph);for(var v:graph.versions().values()){if(v.projectId()!=null&&!j.projectId().equals(v.projectId()))deny();var prior=versions.putIfAbsent(v.id(),v);if(prior!=null&&!prior.equals(v))bad();var rows=sources.source(v.id());if(rows.size()>1)bad();if(!rows.isEmpty()){var source=rows.get(0);same(permitted.get(v.id()),source.rightsRevision());classification=FormalEvaluationContextPackages.max(classification,source.classification(),one(sources.rights(source.rightsRevision())).classification());}if("ARTIFACT".equals(v.entityKind()))classification=FormalEvaluationContextPackages.max(classification,one(artifacts.artifact(v.id())).classification());}}
